<?php
require_once __DIR__.'/../app/Services/SalonRuntimeService.php';
require_once __DIR__.'/../app/Services/SalonStationAccounts.php';
use App\Services\SalonStationAccounts as Accounts;
use App\Services\SalonRuntimeService as Runtime;
$db=new PDO('sqlite::memory:',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);
$db->exec("CREATE TABLE apariencia_almacen(almacen_id INTEGER,almacen_uid TEXT,modo_tienda TEXT); INSERT INTO apariencia_almacen VALUES(1,'salon','salon');
CREATE TABLE configuracion(clave TEXT,valor TEXT,uid TEXT,categoria TEXT,created_at TEXT,updated_at TEXT);
CREATE TABLE usuarios(id INTEGER,estado TEXT,rol TEXT); INSERT INTO usuarios VALUES(7,'ACTIVADO','vendedor');
CREATE TABLE clientes(id INTEGER,uid TEXT,nombre TEXT,almacen_uid TEXT); INSERT INTO clientes VALUES(1,'c1','Ana','salon'),(2,'c2','Otra','other');
CREATE TABLE servicios(id INTEGER,nombre TEXT,precio_venta REAL,estado TEXT,almacen_uid TEXT); INSERT INTO servicios VALUES(1,'Manicura',500,'ACTIVO','salon'),(2,'Inactivo',200,'INACTIVO','salon');
CREATE TABLE accesorios(id INTEGER,nombre TEXT,precio_venta REAL,cantidad INTEGER,almacen_uid TEXT); INSERT INTO accesorios VALUES(1,'Esmalte',100,5,'salon');");
$planning=['stations'=>[['uid'=>'p1','name'=>'Puesto 1','active'=>true]],'stationAssignments'=>[['date'=>'2026-10-15','stationUid'=>'p1','stationName'=>'Puesto 1','userId'=>7,'stylistName'=>'Operadora']]];
$db->prepare('INSERT INTO configuracion(clave,valor) VALUES(?,?)')->execute(['salon_planning_v1_salon',json_encode($planning)]);
$warehouse=['id'=>1,'uid'=>'salon'];$checks=0;
function check($ok,$message) {global $checks;if(!$ok)throw new RuntimeException($message);$checks++;}
function fails($fn,$message) {try{$fn();}catch(Throwable $e){check(true,$message);return;}throw new RuntimeException($message);}
function op($operation,$actor=['rol'=>'cajero']) {global $db,$warehouse;return Runtime::handle($db,'salon:guardarPlanificacion',['warehouse'=>$warehouse,'accountOperation'=>$operation],$actor,false)['data'];}
$save=['type'=>'save','uid'=>'account-1','stationUid'=>'p1','date'=>'2026-10-15','customerId'=>1,'lines'=>[]];
$row=op($save);check($row['data']['operator']['userId']===7,'Operator snapshot missing');
fails(fn()=>op(array_replace($save,['uid'=>'another'])),'Two open accounts in same station');
fails(fn()=>op(array_replace($save,['revision'=>-1])),'Stale revision accepted');
fails(fn()=>op(array_replace($save,['revision'=>0,'customerId'=>2])),'Foreign customer accepted');
fails(fn()=>op(array_replace($save,['revision'=>0,'lines'=>[['table'=>'usuarios','id'=>1,'quantity'=>1]]])),'Arbitrary table accepted');
fails(fn()=>op(array_replace($save,['revision'=>0,'lines'=>[['table'=>'servicios','id'=>2,'quantity'=>1]]])),'Inactive service accepted');
$save['revision']=0;$save['lines']=[['table'=>'servicios','id'=>1,'quantity'=>1],['table'=>'accesorios','id'=>1,'quantity'=>2]];
$row=op($save);check($row['revision']===1 && count($row['data']['cart'])===2,'Account update failed');
check($row['data']['cart'][0]['precio']===500,'Server did not resolve price');
$planning['stationAssignments'][0]['userId']=8;
$db->prepare('UPDATE configuracion SET valor=?')->execute([json_encode($planning)]);
check(op(['type'=>'list','date'=>'2026-10-16'])[0]['data']['operator']['userId']===7,'Assignment change rewrote operator');
App\Services\SalonStationCommissions::setStaff($db,['userId'=>7,'employment'=>'temporary','revision'=>0],['id'=>1],true);
$invoice=['uid'=>'salon_account_invoice_account-1','almacen_uid'=>'salon','estado_factura'=>'PAGADA','cod_cliente'=>'1','vendedor'=>'Operadora','productos'=>json_encode($row['data']['cart']),'otro'=>json_encode(['salon_account'=>['uid'=>'account-1','revision'=>1,'employment'=>'temporary','employmentRevision'=>1,'policyRevision'=>1]])];
fails(fn()=>Accounts::finish($db,array_replace($invoice,['vendedor'=>'Otro'])),'Changed operator accepted');
fails(fn()=>Accounts::finish($db,array_replace($invoice,['productos'=>'[]'])),'Changed lines accepted');
fails(fn()=>Accounts::finish($db,array_replace($invoice,['estado_factura'=>'PENDIENTE'])),'Unpaid invoice closed station');
fails(fn()=>Accounts::finish($db,array_replace($invoice,['otro'=>json_encode(['salon_account'=>['uid'=>'account-1','revision'=>0]])])),'Stale checkout accepted');
$db->exec('BEGIN IMMEDIATE');Runtime::applyDeposit($db,$invoice,[]);$db->exec('ROLLBACK');
check(op(['type'=>'list'])[0]['status']==='OPEN','Failed invoice freed station');
$db->exec('BEGIN IMMEDIATE');Runtime::applyDeposit($db,$invoice,[]);$db->exec('COMMIT');
check(op(['type'=>'list','date'=>'2026-10-15'])[0]['status']==='CLOSED','Paid invoice did not free station');
fails(fn()=>Accounts::finish($db,$invoice),'Second charge accepted');
fails(fn()=>op(array_replace($save,['revision'=>2])),'Closed account edited');
$planning['stationAssignments'][0]['userId']=7;
$db->prepare('UPDATE configuracion SET valor=?')->execute([json_encode($planning)]);
$empty=op(['type'=>'save','uid'=>'clear-1','stationUid'=>'p1','date'=>'2026-10-15','customerId'=>1,'lines'=>[]]);
fails(fn()=>op(['type'=>'clear','uid'=>'clear-1','revision'=>1]),'Stale clear accepted');
fails(fn()=>op(['type'=>'clear','uid'=>'clear-1','revision'=>0],['rol'=>'vendedor']),'Seller cleared a customer');
$cleared=op(['type'=>'clear','uid'=>'clear-1','revision'=>0]);
check($cleared['status']==='CLEARED','Zero balance account not cleared');
check(!array_filter(op(['type'=>'list','date'=>'2026-10-15']),fn($item)=>$item['uid']==='clear-1'),'Cleared account still occupies station');
check($db->query("SELECT status FROM _salon_station_accounts WHERE uid='clear-1'")->fetchColumn()==='CLEARED','Cleared account audit missing');
check(json_decode($db->query("SELECT valor FROM configuracion WHERE clave='salon_planning_v1_salon'")->fetchColumn(),true)['stationAssignments'][0]['userId']===7,'Clearing removed operator assignment');
fails(fn()=>op(['type'=>'clear','uid'=>'clear-1','revision'=>0]),'Cleared account accepted twice');
$filled=op(['type'=>'save','uid'=>'clear-2','stationUid'=>'p1','date'=>'2026-10-15','customerId'=>1,'lines'=>[['table'=>'servicios','id'=>1,'quantity'=>1]]]);
fails(fn()=>op(['type'=>'clear','uid'=>'clear-2','revision'=>0]),'Nonzero account cleared');
$zero=op(['type'=>'save','uid'=>'clear-2','revision'=>0,'customerId'=>1,'lines'=>[]]);
check($zero['revision']===1,'Zero balance update failed');
check(op(['type'=>'clear','uid'=>'clear-2','revision'=>1])['status']==='CLEARED','Updated zero balance account not cleared');
echo "$checks station account checks passed\n";
